import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;

const db = openDatabase();
let stopping = false;
let currentJobId: string | null = null;

const beatStmt = db.prepare(
  `INSERT INTO heartbeat (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`,
);
function heartbeat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}
heartbeat();
const beatTimer = setInterval(heartbeat, 500);

// Recover jobs interrupted by a previous worker crash.
const nowIso = () => new Date().toISOString();
db.prepare(`UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE status = 'running'`).run(
  nowIso(),
);

const claimStmt = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ?
  WHERE seq = (
    SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1
  ) AND status = 'queued'
  RETURNING *
`);
const progressStmt = db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', progress = ?, result_output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const retryStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const failStmt = db.prepare(
  `UPDATE jobs SET status = 'failed', progress = 0, result_output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const requeueStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
);

async function processJob(job: JobRow): Promise<void> {
  currentJobId = job.id;
  try {
    const attempt = job.attempts;
    if (attempt <= job.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) {
        failStmt.run('transient failure', nowIso(), job.id);
      } else {
        retryStmt.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
      }
      return;
    }
    for (let step = 1; step <= job.steps; step++) {
      await sleep(STEP_MS);
      if (stopping) return;
      if (step < job.steps) progressStmt.run(step, nowIso(), job.id);
    }
    completeStmt.run(job.steps, job.input.toUpperCase(), nowIso(), job.id);
  } finally {
    currentJobId = null;
  }
}

function shutdown(): void {
  if (stopping) return;
  stopping = true;
  // Return an interrupted job to the queue so it is picked up on the next start.
  if (currentJobId) {
    try {
      requeueStmt.run(nowIso(), currentJobId);
    } catch (err) {
      console.error(err);
    }
  }
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimStmt.get(nowIso(), Date.now()) as JobRow | undefined;
  } catch (err) {
    console.error('claim failed', err);
  }
  if (job) {
    try {
      await processJob(job);
    } catch (err) {
      console.error('processing failed', err);
    }
  } else {
    await sleep(POLL_MS);
  }
}
clearInterval(beatTimer);
try {
  db.prepare(`DELETE FROM heartbeat WHERE name = 'worker'`).run();
} catch {}
db.close();
console.log('worker stopped');
process.exit(0);

