import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const MAX_BODY = 1024 * 1024;

interface FieldError {
  field: string;
  message: string;
}

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields || err.code === 'invalid_request') error.fields = err.fields ?? [];
  send(res, err.status, { error });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooBig = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY) tooBig = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooBig ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const getJobStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const listJobsStmt = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const byKeyStmt = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const insertStmt = db.prepare(`
  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idempotency_key, payload)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)
  RETURNING *
`);
const heartbeatStmt = db.prepare(`SELECT at FROM heartbeat WHERE name = 'worker'`);

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED = new Set(['input', 'steps', 'failAttempts']);

function isJsonContentType(ct: string | undefined): boolean {
  if (!ct) return false;
  const mime = ct.split(';')[0].trim().toLowerCase();
  return mime === 'application/json' || /^application\/[a-z0-9.+-]+\+json$/.test(mime);
}

function checkInt(value: unknown, field: string, min: number, max: number, errors: FieldError[]): void {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    errors.push({ field, message: `${field} must be an integer` });
  } else if (!Number.isInteger(value)) {
    errors.push({ field, message: `${field} must be an integer` });
